// Money is kept in paise (integers) so 0.1 + 0.2 never becomes 0.30000000000000004.
function toPaise(text) {
  if (!/^\d+(\.\d{1,2})?$/.test(text)) return null;
  const [rupees, frac = ""] = text.split(".");
  return Number(rupees) * 100 + Number((frac + "00").slice(0, 2));
}

function format(paise) {
  const sign = paise < 0 ? "-" : paise > 0 ? "+" : "";
  const abs = Math.abs(paise);
  return `${sign}${Math.floor(abs / 100)}.${String(abs % 100).padStart(2, "0")}`;
}

module.exports = { toPaise, format };

