  }

  lines() {
    // Milestone 1: "<name> <+x.xx|-x.xx|0.00>" sorted by name; skip nobody who ever appeared.
    return [];
  }

  settle() {
    // Milestone 2: repeatedly the person who owes the most pays the person owed the most
