const { toPaise } = require("./money");
const { Group } = require("./split");

const group = new Group();
const out = [];
for (const raw of require("fs").readFileSync(0, "utf8").split("\n")) {
  const p = raw.trim().split(/\s+/).filter(Boolean);
  if (p.length === 0) continue;
  if (p[0] === "PAY" && p.length === 4) {
    const paise = toPaise(p[2]);
    const members = p[3].split(",").filter(Boolean);
    if (paise === null || paise === 0) out.push(`error: bad amount ${p[2]}`);
    else if (members.length === 0 || new Set(members).size !== members.length) out.push("error: bad member list");
    else {
      group.pay(p[1], paise, members);
      out.push(`${p[1]} paid ${p[2]} for ${members.length}`);
    }
  } else if (p[0] === "BALANCE" && p.length === 1) {
    const rows = group.lines();
    out.push(rows.length ? rows.join("\n") : "no expenses");
  } else if (p[0] === "SETTLE" && p.length === 1) {
    const rows = group.settle();
    out.push(rows.length ? rows.join("\n") : "all settled");
  } else out.push(`error: bad command ${raw.trim()}`);
}
