const { format } = require("./money");

class Group {
  constructor() {
    this.balance = new Map(); // name -> paise; positive = is owed money, negative = owes
  }

  #add(name, paise) {
    this.balance.set(name, (this.balance.get(name) ?? 0) + paise);
  }

  pay(payer, paise, members) {
    const share = Math.floor(paise / members.length);
    let left = paise - share * members.length;
    this.#add(payer, paise);
    for (const m of members) {
      const extra = left > 0 ? 1 : 0;
      left -= extra;
      this.#add(m, -(share + extra));
    }
  }

  lines() {
    return [...this.balance.keys()].sort().map((name) => `${name} ${format(this.balance.get(name))}`);
  }

  settle() {
    const owed = new Map(this.balance);
    const pick = (sign) =>
      [...owed.entries()]
        .filter(([, v]) => Math.sign(v) === sign)
        .sort((a, b) => Math.abs(b[1]) - Math.abs(a[1]) || (a[0] < b[0] ? -1 : 1))[0];
    const out = [];
    for (;;) {
      const debtor = pick(-1);
      const creditor = pick(1);
      if (!debtor || !creditor) break;
      const amount = Math.min(-debtor[1], creditor[1]);
      out.push(`${debtor[0]} pays ${creditor[0]} ${format(amount).replace("+", "")}`);
      owed.set(debtor[0], debtor[1] + amount);
      owed.set(creditor[0], creditor[1] - amount);
    }
    return out;
  }
}

module.exports = { Group };
